#!/usr/bin/env python3
"""Compute numeric GT for CSX-093_Q2."""

from __future__ import annotations

import json
import re
from collections import Counter
from pathlib import Path
from typing import Any


TASK_ID = "CSX-093_Q2"
EVENT_ID = "CSX-093"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
OUTPUT_PATH = TASK_DIR / "computed_gt.json"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_001_Locked_package_evidence_report.html",
    "data/event_reports/event_reports_003_Locked_event_anchor_September_2021_Hurricane_Ida_Northeast_flooding.json",
    "data/physical_hazard/physical_hazard_003_Open-Meteo_historical_weather_point_API.json",
    "data/air_quality/air_quality_002_03_city_feedback_or_air_quality_NYC_311_Service_Requests_Socrata_flood_complaints.json.json",
    "data/remote_sensing/remote_sensing_004_Google_Satellite_Embedding_annual_cosine-change_stats.json",
    "data/remote_sensing/remote_sensing_010_sentinel1_vv_change_stats.json.json",
]

RUBRIC_CRITERIA = [
    {
        "name": "JSON shape",
        "points": 3,
        "description": "Returns the six requested top-level fields with threshold_counts nested as specified.",
        "partial_credit": "Award 1-2 points if the answer includes most required fields but has minor nesting, naming, or extra-text problems; award 0 if the required ledger is not recoverable.",
    },
    {
        "name": "Hourly rainfall calculations",
        "points": 5,
        "description": "Computes 133.9 mm event total, 98.3 mm wettest 6-hour load, 0.734 six-hour share, and 23 wet-run hours.",
        "partial_credit": "Award about 1 point for each correct rainfall quantity, with small rounding tolerance; lose the relevant credit for wrong aggregation windows, unit mistakes, or treating trace-zero hours as wet.",
    },
    {
        "name": "Rain thresholds",
        "points": 4,
        "description": "Evaluates all six rain thresholds from report, hourly rainfall, and city record values.",
        "partial_credit": "Award partial credit in proportion to correctly evaluated rain tests; lose credit for missing the inch-to-mm conversion, using the wrong threshold, or miscounting the six-test pass total.",
    },
    {
        "name": "Contrast thresholds",
        "points": 3,
        "description": "Evaluates wind, Sentinel-1 mean VV change, and AlphaEarth mean change checks correctly.",
        "partial_credit": "Award 1 point per correctly evaluated contrast test; lose credit for using the signed Sentinel-1 value instead of its absolute magnitude or reversing a less-than comparison.",
    },
    {
        "name": "Final state",
        "points": 3,
        "description": "Applies the threshold-count rule and returns rainfall_concentration_signature_supported.",
        "partial_credit": "Award 1-2 points if the final label is consistent with one threshold count but the other count or the rule wording is partly wrong; award 0 for the opposite final state.",
    },
    {
        "name": "Formula trace",
        "points": 1,
        "description": "Shows enough formula work to audit rounding and inch-to-mm conversion.",
        "partial_credit": "Award 0.5 point for a mostly clear trace with one missing conversion or rounding note; award 0 if no calculation path is shown.",
    },
    {
        "name": "No overstatement",
        "points": 1,
        "description": "Does not convert service records into verified flood depth or mean image summaries into a complete inundation map.",
        "partial_credit": "Award 0.5 point if the answer has one minor over-broad phrase but keeps the computed ledger intact; award 0 for adding major realized-loss or full-map conclusions beyond the computed values.",
    },
]


def read_json(rel_path: str) -> dict[str, Any] | list[Any]:
    return json.loads((PACKAGE_DIR / rel_path).read_text(encoding="utf-8-sig"))


def read_text(rel_path: str) -> str:
    return (PACKAGE_DIR / rel_path).read_text(encoding="utf-8-sig", errors="replace")


def rolling_max(values: list[float], window: int) -> float:
    if len(values) < window:
        return round(sum(values), 3)
    return round(max(sum(values[i : i + window]) for i in range(len(values) - window + 1)), 3)


def longest_wet_run(values: list[float]) -> int:
    best = 0
    current = 0
    for value in values:
        if value > 0:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best


def central_park_record_hour_mm(report_html: str) -> float:
    match = re.search(r"--\s*(\d+(?:\.\d+)?)\"\s+between", report_html)
    if not match:
        raise ValueError("Central Park record-hour amount not found")
    return round(float(match.group(1)) * 25.4, 1)


def regional_peak_floor_mm(report_html: str) -> float:
    if not re.search(r"just above 10", report_html, re.IGNORECASE):
        raise ValueError("regional peak floor phrase not found")
    return round(10.0 * 25.4, 1)


def compute_values() -> dict[str, Any]:
    event = read_json("metadata/event.json")
    anchor = read_json(
        "data/event_reports/event_reports_003_Locked_event_anchor_September_2021_Hurricane_Ida_Northeast_flooding.json"
    )
    report_html = read_text("data/event_reports/event_reports_001_Locked_package_evidence_report.html")
    meteo = read_json("data/physical_hazard/physical_hazard_003_Open-Meteo_historical_weather_point_API.json")
    records = read_json(
        "data/air_quality/air_quality_002_03_city_feedback_or_air_quality_NYC_311_Service_Requests_Socrata_flood_complaints.json.json"
    )
    alpha = read_json("data/remote_sensing/remote_sensing_004_Google_Satellite_Embedding_annual_cosine-change_stats.json")
    s1 = read_json("data/remote_sensing/remote_sensing_010_sentinel1_vv_change_stats.json.json")

    precipitation = [float(value) for value in meteo["hourly"]["precipitation"]]
    wind = [float(value) for value in meteo["hourly"]["wind_speed_10m"]]
    borough_counts = Counter((row.get("borough") or "UNKNOWN").upper() for row in records)

    event_total = round(sum(precipitation), 1)
    wettest_6h = rolling_max(precipitation, 6)
    six_hour_share = round(wettest_6h / event_total, 3)
    top3_share = round(sum(count for _, count in borough_counts.most_common(3)) / len(records), 3)

    support_values = {
        "regional_peak_floor_mm": regional_peak_floor_mm(report_html),
        "central_park_record_hour_mm": central_park_record_hour_mm(report_html),
        "city_report_total": len(records),
        "top3_borough_share": top3_share,
        "max_point_wind_kmh": round(max(wind), 1),
        "sentinel1_mean_db": round(float(s1["stats"]["s1_vv_post_minus_pre_db_mean"]), 3),
        "alphaearth_mean_change": round(float(alpha["stats"]["alphaearth_1_minus_cosine_mean"]), 4),
    }

    rain_tests = {
        "regional_peak_floor_ge_254mm": support_values["regional_peak_floor_mm"] >= 254.0,
        "central_park_record_hour_ge_75mm": support_values["central_park_record_hour_mm"] >= 75.0,
        "wettest_6h_ge_75mm": wettest_6h >= 75.0,
        "six_hour_share_ge_0_60": six_hour_share >= 0.60,
        "city_report_total_ge_400": support_values["city_report_total"] >= 400,
        "top3_borough_share_ge_0_75": support_values["top3_borough_share"] >= 0.75,
    }
    contrast_tests = {
        "max_point_wind_lt_63kmh": support_values["max_point_wind_kmh"] < 63.0,
        "sentinel1_mean_abs_lt_1db": abs(support_values["sentinel1_mean_db"]) < 1.0,
        "alphaearth_mean_lt_0_05": support_values["alphaearth_mean_change"] < 0.05,
    }

    threshold_counts = {
        "rain": sum(1 for passed in rain_tests.values() if passed),
        "contrast": sum(1 for passed in contrast_tests.values() if passed),
    }
    final_state = (
        "rainfall_concentration_signature_supported"
        if threshold_counts["rain"] >= 5 and threshold_counts["contrast"] >= 2
        else "rainfall_concentration_signature_not_supported"
    )

    primary_gt = {
        "event_total_mm": event_total,
        "wettest_6h_mm": wettest_6h,
        "six_hour_share": six_hour_share,
        "wet_run_hours": longest_wet_run(precipitation),
        "threshold_counts": threshold_counts,
        "final_state": final_state,
    }

    return {
        "event": event,
        "event_window": anchor["temporal_window"],
        "primary_gt": primary_gt,
        "support_values": support_values,
        "rain_tests": rain_tests,
        "contrast_tests": contrast_tests,
    }


def build_output() -> dict[str, Any]:
    values = compute_values()
    primary_gt = values["primary_gt"]
    support_values = values["support_values"]

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": "numeric_diagnosis",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L2",
        "primary_gt": primary_gt,
        "key_values": {
            "regional_peak_floor_mm": support_values["regional_peak_floor_mm"],
            "central_park_record_hour_mm": support_values["central_park_record_hour_mm"],
            "city_report_total": support_values["city_report_total"],
            "top3_borough_share": support_values["top3_borough_share"],
            "max_point_wind_kmh": support_values["max_point_wind_kmh"],
            "sentinel1_mean_db": support_values["sentinel1_mean_db"],
            "alphaearth_mean_change": support_values["alphaearth_mean_change"],
        },
        "formulas": {
            "event_total_mm": "sum(hourly precipitation)",
            "wettest_6h_mm": "max rolling 6-hour precipitation sum",
            "six_hour_share": "wettest_6h_mm / event_total_mm",
            "wet_run_hours": "longest contiguous run of hourly precipitation > 0",
            "rain_pass_count": "count true tests among regional_peak_floor_mm>=254, central_park_record_hour_mm>=75, wettest_6h_mm>=75, six_hour_share>=0.60, city_report_total>=400, top3_borough_share>=0.75",
            "contrast_pass_count": "count true tests among max_point_wind_kmh<63, abs(sentinel1_mean_db)<1, alphaearth_mean_change<0.05",
        },
        "thresholds": {
            "rain": values["rain_tests"],
            "contrast": values["contrast_tests"],
        },
        "support_values": support_values,
        "numeric_tolerances": {
            "event_total_mm": {"value": primary_gt["event_total_mm"], "tolerance": 0.1},
            "wettest_6h_mm": {"value": primary_gt["wettest_6h_mm"], "tolerance": 0.1},
            "six_hour_share": {"value": primary_gt["six_hour_share"], "tolerance": 0.001},
            "wet_run_hours": {"value": primary_gt["wet_run_hours"], "tolerance": 0},
            "regional_peak_floor_mm": {"value": support_values["regional_peak_floor_mm"], "tolerance": 0.1},
            "central_park_record_hour_mm": {"value": support_values["central_park_record_hour_mm"], "tolerance": 0.1},
            "city_report_total": {"value": support_values["city_report_total"], "tolerance": 0},
            "top3_borough_share": {"value": support_values["top3_borough_share"], "tolerance": 0.001},
            "max_point_wind_kmh": {"value": support_values["max_point_wind_kmh"], "tolerance": 0.1},
            "sentinel1_mean_db": {"value": support_values["sentinel1_mean_db"], "tolerance": 0.001},
            "alphaearth_mean_change": {"value": support_values["alphaearth_mean_change"], "tolerance": 0.0001},
        },
        "rubric": {
            "total_points": 20,
            "criteria": RUBRIC_CRITERIA,
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
        "event_summary": {
            "event_name": values["event"]["event_name"],
            "hazard_family": values["event"]["hazard_family"],
            "event_window": values["event_window"],
        },
    }


def main() -> None:
    OUTPUT_PATH.write_text(json.dumps(build_output(), indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
